import{_ as t,o,c as a,ag as i}from"./chunks/framework.cyF4XceO.js";const p=JSON.parse('{"title":"takoform_worker_bundle","description":"Worker Bundle (edge.forms.takoform.com, role revision).","frontmatter":{"page_title":"takoform_worker_bundle Resource - takoform","subcategory":"tako0614 Forms","description":"Worker Bundle (edge.forms.takoform.com, role revision)."},"headers":[],"relativePath":"docs/resources/worker_bundle.md","filePath":"docs/resources/worker_bundle.md"}'),s={name:"docs/resources/worker_bundle.md"};function r(n,e,d,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="takoform-worker-bundle" tabindex="-1">takoform_worker_bundle <a class="header-anchor" href="#takoform-worker-bundle" aria-label="Permalink to &quot;takoform_worker_bundle&quot;">​</a></h1><p>Immutable content-addressed module bundle of one worker build, named by the digest of the artifact manifest committed through the content-addressed upload API (decision 0012). The manifest, not this Form, describes the main module and every additional module with its closed media type, exact size, and sha256 digest, so the bundle keeps exactly one source of truth for its bytes. Different bytes commit a different manifest, which is a different bundle.</p><p>This is a <code>revision</code> resource: an immutable snapshot. It is create-only — every desired attribute forces replacement, and rollback means pointing a deployment at an earlier revision, never editing this one.</p><p>This page documents the publisher-set Provider 4 mapping; its exact FormRef <code>edge.forms.takoform.com/WorkerBundle</code> is recorded below. The resource type is Provider metadata. The published Edge Form Definition is maintained in the <a href="https://github.com/tako0614/takoform-forms/blob/3231633605b737ce5279d7fc020b4780568e7091/forms/candidates/edge.forms.takoform.com/worker-bundle/definition.json" target="_blank" rel="noreferrer">takoform-forms source</a>. See the complete exact identity and the <a href="https://takoform.com/examples/resources/takoform_worker_bundle/resource.tf" target="_blank" rel="noreferrer">complete example</a>.</p><h2 id="exact-formref" tabindex="-1">Exact FormRef <a class="header-anchor" href="#exact-formref" aria-label="Permalink to &quot;Exact FormRef&quot;">​</a></h2><p>This Provider mapping carries the following exact four-field FormRef:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;apiVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;edge.forms.takoform.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;WorkerBundle&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;definitionVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.1.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;schemaDigest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sha256:cb21984a579ae2706bddada8b44a22c0f8390994550c10d7c65df82edfa1141b&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>packageDigest</code> — Form Package digest (separate from FormRef; embedded Provider provenance): <code>sha256:68d5d9ea27bc044cdda1cfc0d96fa4492e67b328bd84861e2e77699d3c5b06a1</code>.</p><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><ul><li><code>name</code> (String, optional, computed, forces replacement) — Portable resource name (<code>metadata.name</code>). Omit it and set <code>revision_owner</code> instead: this Form is an immutable revision, so the provider derives <code>bundle-&lt;content digest prefix&gt;-&lt;owner digest prefix&gt;</code> from this revision&#39;s own content and its declared owner. Changed content is then a NEW revision created beside the old one, which is the only way a code change applies at all — a host refuses every update to a revision, and replacing one under a name it still holds completes in neither apply order. Setting it pins the name, which an imported revision needs; the provider then refuses at plan time any change that would replace this revision under it.</li><li><code>revision_owner</code> (String, optional, forces replacement) — Stable name of the logical resource that owns this revision. When the Form carries an owner relation, use that target resource&#39;s name. Required whenever <code>name</code> is omitted. Two independent resources built from identical content derive identical content digests, so without an owner they would derive one name and two Terraform resources would manage one host address — where a destroy of either breaks the other. It is provider-side authoring input: no wire member carries it, the host never sees it, and it enters only the derived name. The repository <a href="https://github.com/tako0614/terraform-provider-takoform/tree/main/modules/worker-app" target="_blank" rel="noreferrer"><code>worker-app</code> module</a> sets it for you.</li><li><code>manifest_digest</code> (String, optional, computed, forces replacement) — Immutable digest of the committed artifact manifest this bundle is. It is the whole portable desired state: the manifest, not this resource, describes the modules. Declare exactly one of the two authoring modes — reference a manifest already committed to the host by setting this digest, or leave it unset and author the bundle locally with the two arguments below. Writing it alongside local authoring is accepted only when the authored bytes commit exactly that manifest; a disagreement is refused before any host call.</li><li><code>main_module</code> (String, optional, forces replacement) — Local authoring only: relative path of the ES module the runtime instantiates first; it must name one declared module. It is not portable desired state; it describes the artifact manifest the provider commits.</li><li><code>modules</code> (List of Object, optional, forces replacement) — Local authoring only: every module of the bundle. Each entry declares <code>name</code>, <code>content_type</code> (one of the five closed media types), and <code>content_file</code> (a local file path). The provider reads each file, computes its exact <code>size</code> and sha256 <code>digest</code> (both computed attributes), commits the artifact manifest through the content-addressed artifact API, and records the returned <code>manifest_digest</code>. File paths stay in state; file bytes never do. At every plan against existing state the provider re-reads and re-hashes each <code>content_file</code>: changed bytes at an unchanged path change the planned manifest digest and force replacement.</li><li><code>space</code> (String, optional, forces replacement) — Exact opaque SpaceID; overrides the provider default.</li><li><code>create_timeout</code> / <code>delete_timeout</code> (String, optional) — Go durations bounding each operation (defaults <code>20m</code> / <code>30m</code>). There is no <code>update_timeout</code>: this Form declares no update capability. Changing only these provider-side timeouts is applied in place without any host call.</li></ul><h2 id="read-only-attributes" tabindex="-1">Read-only attributes <a class="header-anchor" href="#read-only-attributes" aria-label="Permalink to &quot;Read-only attributes&quot;">​</a></h2><ul><li><code>uid</code> — host-issued immutable resource identity; delete and re-create yields a new UID.</li><li><code>generation</code> — desired-state generation; increments only when the portable desired spec changes; this Form declares no update capability — every desired attribute forces replacement instead. It is also the DELETE fence, because a delete withdraws desired state like any other desired-state mutation.</li><li><code>revision</code> — representation revision; increments whenever the representation changes — a spec-changing update, new status, new outputs, or a change to another resource this one is rendered from. It is the strong ETag, and it is deliberately NOT the delete fence: a teardown removes dependents first and would otherwise be refused by a revision it moved itself.</li><li><code>conditions</code> — the complete status condition list the host reports, in its order. Each entry carries <code>type</code> (the closed <code>Ready</code> / <code>Reconciling</code> / <code>Degraded</code> / <code>Drifted</code> / <code>Blocked</code> / <code>Deleting</code> vocabulary), <code>status</code> (<code>True</code> / <code>False</code> / <code>Unknown</code>), the closed portable <code>reason</code>, an optional <code>message</code>, an optional non-portable <code>host_reason</code> naming exactly what is wrong, the <code>observed_generation</code> the status reflects, and <code>last_transition_time</code>. Conditions are host-rendered state: they change when this resource changes AND when a resource it depends on changes, with no desired spec changing anywhere, so they are read-only and a configuration must not assert them.</li><li><code>ready</code> — derived convenience: true when <code>conditions</code> carries the closed <code>Ready</code> condition with status <code>True</code>. Read <code>conditions</code> for the reason it is not.</li><li><code>outputs_json</code> — the WHOLE <code>status.outputs</code> document, JSON-serialized. This Form declares no <code>outputSchema</code>, so a conforming host omits <code>status.outputs</code> entirely and this attribute is <code>&quot;{}&quot;</code>. It stays declared because a host may publish a value no contract describes, and an undescribed value must still be reachable rather than silently dropped.</li><li><code>form_api_version</code>, <code>form_kind</code>, <code>form_definition_version</code>, <code>form_schema_digest</code> — the exact immutable FormRef this state is bound to; reads dispatch on it.</li><li><code>form_package_digest</code> — audit-only package provenance; never part of resource identity, queries, or fences.</li><li><code>relation_drift_reason</code> — internal recovery only: <code>ExternalChange</code> or <code>DependencyMissing</code> while the host reports that a resource this one references was replaced or removed out of band, null otherwise. A refresh reports the break as a warning and keeps the resource in state; the next plan then proposes replacing this resource, because this Form declares no in-place update and a host refuses every apply to the existing one. It is provider-side recovery bookkeeping — no portable wire member carries it — and configurations must not depend on it.</li><li><code>pending_operation_id</code> — internal recovery only: the host operation id of a mutation the host accepted but that did not reach a terminal state before the operation deadline, null in steady state. A refresh consults it before it reads the resource, and it is cleared only once that operation settles. It is not resource identity and configurations must not depend on it.</li></ul><h2 id="state-continuity" tabindex="-1">State continuity <a class="header-anchor" href="#state-continuity" aria-label="Permalink to &quot;State continuity&quot;">​</a></h2><ul><li><strong>Reads dispatch on the recorded FormRef.</strong> <code>WorkerBundle</code> state is addressed under the exact <code>form_*</code> identity it records, not under this build&#39;s default create ref, so a resource created before the Form line advanced stays addressable as itself. An identity this provider build carries no codec for is a hard error naming that identity and the ones the build does carry; the provider never substitutes another exact FormRef, because a substituted query&#39;s &quot;not found&quot; is indistinguishable from deletion.</li><li><strong>A changed <code>uid</code> is an error, and state is kept.</strong> When the host serves a different <code>uid</code> under the recorded name, the resource this state was applied against is gone and something re-used its name. The provider reports a hard error naming both uids and keeps the resource in state. It does not re-bind — that would adopt a resource you never applied — and it does not remove state, which would make the next apply fail against the resource that does exist, with no plan left to repair it. Resolve it by importing the new incarnation explicitly, restoring the prior one, or deleting the host-side replacement.</li><li><strong>An unfinished mutation is resumed, not re-created.</strong> When <code>pending_operation_id</code> is set, a refresh asks the host about that operation before it reads the resource. While the operation is still running the resource may legitimately not exist yet, so its absence is not treated as deletion and the marker survives; a terminal success is verified against the exact identity and settles state; a terminal failure or an expired operation record defers to an exact read of the resource, which decides. Refresh again once the host settles.</li></ul><h2 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h2><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">terraform import takoform_worker_bundle.example NAME</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">terraform import takoform_worker_bundle.example SPACE/NAME</span></span></code></pre></div><p>Both short forms bind state to this provider build&#39;s default create FormRef. To adopt a resource created under an EARLIER definition version of this Form, name the exact identity instead. The import ID is then one JSON object — not a delimiter-joined string, because a SpaceID is opaque UTF-8 whose only forbidden character is <code>/</code>, so no separator can escape it safely:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">terraform import takoform_worker_bundle.example \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &#39;{&quot;space&quot;:&quot;prod&quot;,&quot;apiVersion&quot;:&quot;edge.forms.takoform.com&quot;,&quot;kind&quot;:&quot;WorkerBundle&quot;,&quot;definitionVersion&quot;:&quot;0.1.0&quot;,&quot;schemaDigest&quot;:&quot;sha256:…&quot;,&quot;name&quot;:&quot;…&quot;}&#39;</span></span></code></pre></div><p><code>space</code> is optional and falls back to the provider default; the four FormRef members are all-or-nothing. An identity this provider build carries no codec for is refused, naming the identities it does carry — it is never silently rebound to the default.</p><p>An imported bundle restores <code>manifest_digest</code> from the host and leaves <code>main_module</code> and <code>modules</code> null: those are local authoring facts the wire never echoes. The resource is fully manageable afterwards — a configuration that states the same <code>manifest_digest</code> plans empty, and adopting the local files that commit exactly that manifest is not a change either, because the bundle&#39;s identity is the digest.</p>`,20)])])}const m=t(s,[["render",r]]);export{p as __pageData,m as default};
